    Fragment f;
    f.local  = v_local;
    f.norm   = v_norm;
    f.frag   = gl_FragCoord.xy;
    f.half_size = v_half;
    f.uv     = v_uv;
    f.color  = v_color;
    f.color2 = v_color2;
    f.radii  = v_radii;
    f.axis   = v_axis;
    f.params = v_params;
